import org.apache.flink.streaming.api.functions.source.legacy.SourceReader;
import org.apache.flink.streaming.api.functions.source.legacy.SourceReaderContext;
import org.apache.flink.streaming.api.functions.source.legacy.SplitEnumerator;
import org.apache.flink.streaming.api.functions.source.legacy.SplitEnumeratorContext;
import org.apache.flink.streaming.api.functions.source.legacy.StaticFileSplitEnumerator;
import org.apache.flink.streaming.api.functions.source.legacy.StaticFileSplitReader;
import org.apache.flink.streaming.api.functions.source.legacy.TextInputFormat;
import org.apache.flink.streaming.api.functions.source.legacy.TimestampedInputSplit;
import org.apache.flink.streaming.api.functions.source.legacy.legacy;
import org.apache.flink.streaming.api.functions.sink.filesystem.rollingpolicies.DefaultRollingPolicy;
import org.apache.flink.streaming.api.windowing.assigners.EventTimeSessionWindows;
import org.apache.flink.streaming.api.windowing.time.Time;
import org.apache.flink.streaming.api.windowing.windows.TimeWindow;
import org.apache.flink.streaming.api.windowing.functions.ProcessWindowFunction;
import org.apache.flink.util.Collector;

import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.HashMap;
import java.util.Map;
import java.util.zip.GZIPInputStream;

public class LongestSessionPerJob extends AppBase {

    private static final int TASK_SUBMIT = 0;
    private static final long MICROS_PER_SECOND = 1_000_000L;
    private static final int JOB_FINISH = 4;

    public static void main(String[] args) throws Exception {

        ParameterTool params = ParameterTool.fromArgs(args);
        String taskInput = params.get("task_input", null);
        String jobInput = params.get("job_input", null);
        String outputPath = params.get("output", null);
        final int sesssize = params.getInt("sesssize", 600);

        StreamExecutionEnvironment env = StreamExecutionEnvironment.getExecutionEnvironment();
        env.setParallelism(1);

        DataStream<TaskEvent> taskEvents = env
                .fromCollection(readTaskEvents(taskInput))
                .assignTimestampsAndWatermarks(
                        WatermarkStrategy
                                .<TaskEvent>forMonotonousTimestamps()
                                .withTimestampAssigner((event, timestamp) -> event.timestamp / 1000L)
                );

        DataStream<Tuple2<Long, Integer>> longestStages = taskEvents
                .filter(event -> event.eventType == TASK_SUBMIT)
                .keyBy(event -> event.jobId)
                .window(EventTimeSessionWindows.withGap(Time.seconds(sesssize)))
                .process(new ProcessWindowFunction<TaskEvent, Tuple2<Long, Integer>, Long, TimeWindow>() {
                    @Override
                    public void process(Long key, Context context, Iterable<TaskEvent> elements, Collector<Tuple2<Long, Integer>> out) {
                        int count = 0;
                        for (TaskEvent ignored : elements) {
                            count++;
                        }
                        out.collect(Tuple2.of(key, count));
                    }
                })
                .keyBy(value -> value.f0)
                .maxBy(1);

        DataStream<JobEvent> jobEvents = env
                .fromCollection(readJobEvents(jobInput))
                .assignTimestampsAndWatermarks(
                        WatermarkStrategy
                                .<JobEvent>forMonotonousTimestamps()
                                .withTimestampAssigner((event, timestamp) -> event.timestamp / 1000L)
                );

        DataStream<String> output = longestStages
                .connect(jobEvents.filter(event -> event.eventType == JOB_FINISH).map(event -> Tuple2.of(event.jobId, -1)))
                .keyBy(value -> value.f0, value -> value.f0)
                .process(new KeyedProcessFunction<Long, Tuple2<Long, Integer>, String>() {
                    private transient ValueState<Integer> maxStage;
                    private transient ValueState<Boolean> finished;

                    @Override
                    public void open(Configuration parameters) {
                        maxStage = getRuntimeContext().getState(new ValueStateDescriptor<>("maxStage", Types.INT));
                        finished = getRuntimeContext().getState(new ValueStateDescriptor<>("finished", Types.BOOLEAN));
                    }

                    @Override
                    public void processElement(Tuple2<Long, Integer> value, Context ctx, Collector<String> out) throws Exception {
                        if (value.f1 == -1) {
                            Integer max = maxStage.value();
                            if (finished.value() == null || !finished.value()) {
                                out.collect("(" + value.f0 + "," + (max == null ? 0 : max) + ")");
                                finished.update(true);
                            }
                            return;
                        }

                        Integer current = maxStage.value();
                        if (current == null || value.f1 > current) {
                            maxStage.update(value.f1);
                        }
                    }
                });

        output.writeAsText(outputPath, FileSystem.WriteMode.OVERWRITE);

        env.execute("LongestSessionPerJob");
    }

    private static java.util.List<TaskEvent> readTaskEvents(String path) throws Exception {
        java.util.List<TaskEvent> events = new java.util.ArrayList<>();
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(new GZIPInputStream(new java.io.FileInputStream(path)), StandardCharsets.UTF_8))) {
            String line;
            while ((line = reader.readLine()) != null) {
                if (!line.isEmpty()) {
                    events.add(TaskEvent.fromCsv(line));
                }
            }
        }
        return events;
    }

    private static java.util.List<JobEvent> readJobEvents(String path) throws Exception {
        java.util.List<JobEvent> events = new java.util.ArrayList<>();
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(new GZIPInputStream(new java.io.FileInputStream(path)), StandardCharsets.UTF_8))) {
            String line;
            while ((line = reader.readLine()) != null) {
                if (!line.isEmpty()) {
                    events.add(JobEvent.fromCsv(line));
                }
            }
        }
        return events;
    }
}
