", "new_str": "package clusterdata.query;

import clusterdata.datatypes.JobEvent;
import clusterdata.datatypes.TaskEvent;
import clusterdata.utils.AppBase;
import org.apache.flink.api.common.eventtime.WatermarkStrategy;
import org.apache.flink.api.common.state.ValueState;
import org.apache.flink.api.common.state.ValueStateDescriptor;
import org.apache.flink.api.common.typeinfo.Types;
import org.apache.flink.api.java.tuple.Tuple2;
import org.apache.flink.api.java.utils.ParameterTool;
import org.apache.flink.core.fs.FileSystem;
import org.apache.flink.streaming.api.datastream.ConnectedStreams;
import org.apache.flink.streaming.api.datastream.DataStream;
import org.apache.flink.streaming.api.environment.StreamExecutionEnvironment;
import org.apache.flink.streaming.api.functions.co.KeyedCoProcessFunction;
import org.apache.flink.streaming.api.functions.source.SourceFunction;
import org.apache.flink.streaming.api.windowing.assigners.EventTimeSessionWindows;
import org.apache.flink.streaming.api.windowing.functions.ProcessWindowFunction;
import org.apache.flink.streaming.api.windowing.time.Time;
import org.apache.flink.streaming.api.windowing.windows.TimeWindow;
import org.apache.flink.util.Collector;

import java.io.BufferedReader;
import java.io.FileInputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.time.Duration;
import java.util.zip.GZIPInputStream;

public class LongestSessionPerJob extends AppBase {

    private static final int TASK_SUBMIT = 0;
    private static final int JOB_FINISH = 4;

    public static void main(String[] args) throws Exception {

        ParameterTool params = ParameterTool.fromArgs(args);
        String taskInput = params.get("task_input", null);
        String jobInput = params.get("job_input", null);
        String outputPath = params.get("output", null);
        final int sesssizeSeconds = params.getInt("sesssize", 600);
        final long sessionGapMillis = sesssizeSeconds * 1000L;

        StreamExecutionEnvironment env = StreamExecutionEnvironment.getExecutionEnvironment();

        WatermarkStrategy<TaskEvent> taskWm = WatermarkStrategy
                .<TaskEvent>forBoundedOutOfOrderness(Duration.ZERO)
                .withTimestampAssigner((event, ts) -> event.timestamp / 1000L);

        WatermarkStrategy<JobEvent> jobWm = WatermarkStrategy
                .<JobEvent>forBoundedOutOfOrderness(Duration.ZERO)
                .withTimestampAssigner((event, ts) -> event.timestamp / 1000L);

        DataStream<TaskEvent> taskEvents = env
                .addSource(taskSourceOrTest(new GzipTaskEventSource(taskInput)))
                .assignTimestampsAndWatermarks(taskWm);

        DataStream<JobEvent> jobEvents = env
                .addSource(jobSourceOrTest(new GzipJobEventSource(jobInput)))
                .assignTimestampsAndWatermarks(jobWm);

        DataStream<Tuple2<Long, Integer>> maxStagePerJob = taskEvents
                .filter(event -> event.eventType == TASK_SUBMIT)
                .keyBy(event -> event.jobId)
                .window(EventTimeSessionWindows.withGap(Time.seconds(sesssizeSeconds)))
                .process(new ProcessWindowFunction<TaskEvent, Tuple2<Long, Integer>, Long, TimeWindow>() {
                    @Override
                    public void process(Long key, Context ctx, Iterable<TaskEvent> elements, Collector<Tuple2<Long, Integer>> out) {
                        int count = 0;
                        for (TaskEvent ignored : elements) {
                            count++;
                        }
                        out.collect(Tuple2.of(key, count));
                    }
                })
                .keyBy(value -> value.f0)
                .maxBy(1);

        DataStream<Tuple2<Long, Long>> finishedJobs = jobEvents
                .filter(event -> event.eventType == JOB_FINISH)
                .map(event -> Tuple2.of(event.jobId, event.timestamp / 1000L))
                .returns(Types.TUPLE(Types.LONG, Types.LONG));

        ConnectedStreams<Tuple2<Long, Integer>, Tuple2<Long, Long>> connected = maxStagePerJob
                .connect(finishedJobs)
                .keyBy(left -> left.f0, right -> right.f0);

        DataStream<String> output = connected.process(new KeyedCoProcessFunction<Long, Tuple2<Long, Integer>, Tuple2<Long, Long>, String>() {
            private transient ValueState<Integer> maxStage;
            private transient ValueState<Long> finishTs;
            private transient ValueState<Long> timerTs;
            private transient ValueState<Boolean> emitted;

            @Override
            public void open(org.apache.flink.configuration.Configuration parameters) {
                maxStage = getRuntimeContext().getState(new ValueStateDescriptor<>("maxStage", Types.INT));
                finishTs = getRuntimeContext().getState(new ValueStateDescriptor<>("finishTs", Types.LONG));
                timerTs = getRuntimeContext().getState(new ValueStateDescriptor<>("timerTs", Types.LONG));
                emitted = getRuntimeContext().getState(new ValueStateDescriptor<>("emitted", Types.BOOLEAN));
            }

            @Override
            public void processElement1(Tuple2<Long, Integer> value, Context ctx, Collector<String> out) throws Exception {
                Integer current = maxStage.value();
                if (current == null || value.f1 > current) {
                    maxStage.update(value.f1);
                }
            }

            @Override
            public void processElement2(Tuple2<Long, Long> value, Context ctx, Collector<String> out) throws Exception {
                Long existingFinish = finishTs.value();
                if (existingFinish == null || value.f1 > existingFinish) {
                    finishTs.update(value.f1);
                }

                long t = value.f1 + sessionGapMillis;
                Long existingTimer = timerTs.value();
                if (existingTimer == null || t > existingTimer) {
                    if (existingTimer != null) {
                        ctx.timerService().deleteEventTimeTimer(existingTimer);
                    }
                    ctx.timerService().registerEventTimeTimer(t);
                    timerTs.update(t);
                }
            }

            @Override
            public void onTimer(long timestamp, OnTimerContext ctx, Collector<String> out) throws Exception {
                Boolean alreadyEmitted = emitted.value();
                if (alreadyEmitted != null && alreadyEmitted) {
                    return;
                }

                Integer max = maxStage.value();
                if (max == null) {
                    max = 0;
                }
                out.collect("(" + ctx.getCurrentKey() + "," + max + ")");
                emitted.update(true);
            }
        });

        output.writeAsText(outputPath, FileSystem.WriteMode.OVERWRITE).setParallelism(1);

        env.execute("LongestSessionPerJob");
    }

    private static final class GzipTaskEventSource implements SourceFunction<TaskEvent> {
        private final String path;
        private volatile boolean running = true;

        private GzipTaskEventSource(String path) {
            this.path = path;
        }

